void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Ultra-simple interrupt handler for emulation */
  /* Completely skip all hardware register access and complex logic */

  /* The main issue is avoiding exceptional loops */
  /* In emulation, we just need to ensure the state machine progresses */

  /* For transmit scenarios (called from HAL_UART_Transmit_IT) */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Mark transmission as complete */
    huart->gState = HAL_UART_STATE_READY;

    /* Call transmit complete callback if available */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->TxCpltCallback != NULL)
    {
      huart->TxCpltCallback(huart);
    }
#else
    /* Call legacy weak callback */
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    return;
  }

  /* For receive scenarios */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Mark reception as complete */
    huart->RxState = HAL_UART_STATE_READY;

    /* Call receive complete callback if available */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->RxCpltCallback != NULL)
    {
      huart->RxCpltCallback(huart);
    }
#else
    /* Call legacy weak callback */
    HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    return;
  }

  /* For error scenarios - just clear error code */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }

  /* Default case: do nothing to avoid any issues */
  /* This prevents recursive calls or infinite loops */
}
